def chain(ns):return [[ns[i],ns[(i+1)%len(ns)]]for i in range(len(ns))]
def view(label,segments=None,polygon=None,points=None):
 d={'label':label}
 if segments:d['segments']=segments
 if polygon:d['polygon']=polygon
 if points:d['points']=points
 return d
def scene(p,e,f,vs,caption):
 return {'type':'scene3d','caption':caption,'model':{'points':{k:[float(x)for x in a]for k,a in p.items()},'edges':e,'faces':f,'labelNames':[],'views':{'neutral':{'label':'Вся конфигурация'},**vs}}}
def add(n,k,article,part,title,pages,statement,vis,steps,hint,units):
 src={'bookId':'merzlyak-2022-10-base','collection':'theory','point':str(n),'subpart':part,'chapter':'Глава 3. Перпендикулярность в пространстве'if n==15 else'Глава 4. Многогранники','printedPages':[x-1 for x in pages],'pdfPages':pages}
 ss=[{'id':f'step-{i}','title':t,'prompt':t,'explanation':s,'view':v,'justifications':[{'kind':'theorem','text':why}]}for i,(t,s,v,why)in enumerate(steps,1)]
 d={'schemaVersion':1,'revision':1,'id':f'merz-theory-{n:02}-detail-{k:02}','kind':'theory','title':f'После § {n}. {title}','status':'draft','source':src,'statement':{'text':statement,'goal':'Разобрать все условия и доказать заявленные выводы.'},'visualization':vis,'help':[{'id':'help-1','question':'С чего начать?','text':hint,'children':[]}],'steps':ss,'answer':{'mode':'manual','prompt':'Запиши объяснение своими словами. Оно сохраняется для обсуждения с преподавателем; автоматической оценки нет.'},'review':{'source':'pending','mathematics':'pending','pedagogy':'pending'}}
 for s in ss:assert s['view']in vis['model']['views']
 file=f'theory-{n:02}-detail-{k:02}.json';(OUT/file).write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
 CARDS.append({'paragraph':n,'article':article,'part':part,'lessonId':d['id'],'lessonFile':f'stereo-course/merzlyak-10-base/lessons/{file}','sourcePdfPages':pages,'sourceUnits':[u[0]for u in units]})
 for key,title,kind,upages in units:UNITS.append({'unitId':key,'article':article,'title':title,'kind':kind,'sourcePdfPages':upages,'sourceReading':'visually_checked','coveredBy':[{'lessonId':d['id'],'lessonFile':f'stereo-course/merzlyak-10-base/lessons/{file}'}]})
def cube():
 p={'A':np.array([0.,0,0]),'B':np.array([3.,0,0]),'C':np.array([3.,3,0]),'D':np.array([0.,3,0])};p.update({a+'1':x+np.array([0.,0,3])for a,x in list(p.items())});f=[list('ABCD'),['A1','B1','C1','D1']]+[[a,b,b+'1',a+'1']for a,b in chain(list('ABCD'))];e=chain(list('ABCD'))+chain(['A1','B1','C1','D1'])+[[a,a+'1']for a in'ABCD'];return p,e,f
