p={'A':[-2,0,2],'A2':[2,0,2],'B':[0,-2,0],'B2':[0,2,0],'C':[-1,-1,1],'C2':[1,1,1],'O':[0,0,1],'P':[-2,-2,1],'Q':[2,-2,1],'R':[2,2,1],'T':[-2,2,1],'U':[-2,-2,2],'V':[2,-2,2],'W':[2,2,2],'Z':[-2,2,2],'U1':[-2,-2,0],'V1':[2,-2,0],'W1':[2,2,0],'Z1':[-2,2,0]}
