DODECA=list(itertools.product([-1,1],repeat=3))+[(0,a/phi,b*phi)for a,b in itertools.product([-1,1],repeat=2)]+[(a/phi,b*phi,0)for a,b in itertools.product([-1,1],repeat=2)]+[(a*phi,0,b/phi)for a,b in itertools.product([-1,1],repeat=2)]
ICO=[(0,a,b*phi)for a,b in itertools.product([-1,1],repeat=2)]+[(a,b*phi,0)for a,b in itertools.product([-1,1],repeat=2)]+[(a*phi,0,b)for a,b in itertools.product([-1,1],repeat=2)]
OCTA=[tuple(s if i==j else 0 for i in range(3))for j in range(3)for s in[-1,1]]
p,e,f=cube();vis=scene(p,e,f,{'face':view('Квадратная грань',None,list('ABCD')),'vertex':view('Три ребра при A',[['A','B'],['A','D'],['A','A1']])},'Куб — один из пяти выпуклых правильных многогранников; все6 граней — одинаковые квадраты.')
add(19,2,PLATO,'статья: определение правильного многогранника и первые примеры','Что делает многогранник правильным',[176,177,178],'Сформулируйте определение правильного многогранника. Проверьте его для куба и правильного тетраэдра; объясните, почему одного красивого или симметричного рисунка недостаточно.',vis,[('Три требования определения','Правильный многогранник должен быть выпуклым; все его грани должны быть равными правильными многоугольниками; в каждой вершине должно сходиться одно и то же число рёбер. Правильный многоугольник имеет равные стороны и равные углы. Выпуклость и одинаковая структура всех вершин — отдельные условия.','face','Определение статьи; определения правильного многоугольника и выпуклости.'),('Проверим куб','У куба6 одинаковых квадратных граней. В каждой из8 вершин сходятся3 ребра. Куб выпуклый: относительно плоскости любой грани остальные точки лежат в одном полупространстве. Все условия выполнены. Другое название куба — гексаэдр, то есть шестигранник.','vertex','Непосредственная проверка определения.'),('Проверим правильный тетраэдр','У правильного тетраэдра4 равных равносторонних треугольных грани и по3 ребра при каждой из4 вершин; он выпуклый. Поэтому он тоже правильный многогранник. Его точная модель и проверка равенства6 рёбер есть в уроке «Когда правильная треугольная пирамида — правильный тетраэдр» после§18. Обычная правильная треугольная пирамида может иметь боковые рёбра другой длины и не удовлетворять определению.','face','Определение правильного тетраэдра; theory18-detail04.'),('Почему важен полный набор условий?','Прямоугольный параллелепипед с разными измерениями выпуклый и имеет по3 ребра в вершине, но его грани не являются одинаковыми квадратами. Поэтому он не правильный многогранник. Слово «правильный» здесь задаёт точные свойства, а не художественную оценку. Название «платоновы тела» связано с древнегреческой традицией и философией Платона; геометрическое определение от этих представлений не зависит.','vertex','Разделение определения, контрпримера и исторического названия.')],'Проверяйте отдельно выпуклость, форму и равенство граней, затем число рёбер при каждой вершине.',[('plato-definition','Правильный многогранник: полное определение','definition',[176]),('plato-cube-example','Куб/гексаэдр как правильный многогранник','example',[177]),('plato-tetrahedron-example','Самостоятельная проверка правильности тетраэдра','proof_prompt',[177]),('plato-history-name','Платоновы тела: название и исторический контекст','context',[178])])
for k,coords,name,face_count,face_sides,degree,pages,part in [(3,DODECA,'Додекаэдр',12,5,3,[176,177,178,179,180],'додекаэдр'),(4,OCTA,'Октаэдр',8,3,4,[177,178],'октаэдр'),(5,ICO,'Икосаэдр',20,3,5,[177,178,179],'икосаэдр')]:
 p,e,f=hull_model(coords);first=next(iter(p));neighbors=[b if a==first else a for a,b in e if first in[a,b]]
 vs={'face':view('Одна правильная грань',None,f[0]),'vertex':view(f'{degree} рёбер при вершине',[[first,x]for x in neighbors])}
 vis=scene(p,e,f,vs,f'{name}: точная геометрическая модель, {len(p)} вершин, {len(e)} рёбер, {len(f)} граней. Невидимые грани не исчезают из тела; вращайте модель.')
 steps=[('Проверим грани',f'У модели {face_count} граней. Каждая — правильный {"пятиугольник с углами108°" if face_sides==5 else "треугольник с углами60°"}. Все грани равны между собой. Они образуют замкнутую выпуклую поверхность; тело находится с одной стороны от плоскости каждой грани.','face','Определение правильного многогранника; построенная точная модель.'),('Проверим вершины',f'При каждой вершине сходятся {degree} {"ребра"if degree in[3,4]else"рёбер"} и {degree} {"грани"if degree in[3,4]else"граней"}. Всего вершин {len(p)}, рёбер {len(e)}. Проверка двойным счётом: {face_count}·{face_sides}=2·{len(e)} и {len(p)}·{degree}=2·{len(e)}. Каждое ребро принадлежит двум граням и имеет два конца.','vertex','Подсчёт инцидентностей грань–ребро и вершина–ребро.')]
 if k==4:
  steps.append(('Как собрать октаэдр из пирамид?','Соединим две равные правильные четырёхугольные пирамиды общим квадратным основанием, расположив вершины по разные стороны основания. Если сторона квадрата a, а высота каждой пирамиды a/√2, то её боковое ребро √((a/√2)²+(a/√2)²)=a. Все8 внешних граней — равносторонние треугольники. Общий квадрат внутри, поэтому в поверхность не входит.','neutral','Теорема Пифагора; соединение двух правильных пирамид.'))
 elif k==3:
  steps.append(('Имя и природные формы','Название означает «двенадцатигранник». На фото в статье некоторые кристаллы пирита напоминают додекаэдр. Природная форма лишь приближает геометрический образ: по одной фотографии нельзя заключать, что все её пятиугольники правильные. Модель здесь удовлетворяет определению точно.','face','Число граней и различие физического объекта с его математической моделью.'))
 else:
  steps.append(('Почему не возникает противоречия при пяти гранях?','При вершине сходятся5 углов по60°, их сумма300° меньше360°. Поэтому грани могут образовать пространственную вершину. В статье упомянуты вирусные оболочки, напоминающие икосаэдр: это пример применения формы, а не замена геометрической проверки.','vertex','Сумма плоских углов при вершине выпуклого многогранника меньше360°.'))
 add(19,k,PLATO,f'статья: {part} и его свойства',name,pages,f'Проверьте на модели все условия правильности {part}а и назовите числа его граней, рёбер и вершин.',vis,steps,'Сначала выделите одну грань, затем одну вершину. Не считайте только видимые на экране грани.',[(f'plato-{part}',f'{name}: определение, пример и свойства','example',pages)]+([('plato-octahedron-two-pyramids','Построение октаэдра из двух квадратных пирамид','construction',[177,178])]if k==4 else[]))
p,e,f=hull_model(OCTA);first=next(iter(p));neighbors=[b if a==first else a for a,b in e if first in[a,b]]
neighbors.sort(key=lambda x:math.atan2(p[x][2],p[x][1]));section=[]
for i,x in enumerate(neighbors,1):name=f'V{i}';p[name]=(p[first]+p[x])/2;section.append(name)
vis=scene(p,e,f,{'vertex':view('В октаэдре k=4, n=3',[[first,x]for x in neighbors]),'section':view('Малый срез V₁V₂V₃V₄ у вершины S=P₁',[[first,x]for x in section],section)},'Октаэдр иллюстрирует один из пяти допустимых типов. Остальные четыре типа представлены отдельными точными моделями.')
add(19,6,PLATO,'статья: почему возможны только пять типов','Пять типов платоновых тел',[178,179,180],'Выведите все возможные пары: число сторон грани n и число рёбер при вершине k. Различайте необходимое неравенство и существование конкретных тел.',vis,[('Почему сумма углов меньше360°?','На модели S=P₁. Выпуклый многогранный угол пересечём плоскостью, отделяющей его вершину S и пересекающей все рёбра. Получим выпуклый m-угольник V₁…Vₘ. В каждой Vᵢ сумма углов между VᵢS и двумя соседними сторонами больше внутреннего угла многоугольника: это строгое неравенство для плоских углов невырожденного трёхгранного угла (доказано в проекте3). Сложим: m·180°−Σ∠VᵢSVᵢ₊₁ > (m−2)·180°. Отсюда Σ∠VᵢSVᵢ₊₁<360°.','section','Неравенство плоских углов трёхгранного угла; суммы углов треугольника и выпуклого многоугольника.'),('Запишем ограничение','Угол правильного n-угольника равен180°(n−2)/n. При вершине сходятся k таких углов, поэтому k·180°(n−2)/n<360°. При n≥3 и k≥3 это равносильно n<2+4/(k−2).','vertex','Условия правильности и формула угла правильного многоугольника.'),('Почему k не может быть6 или больше?','Если k≥6, то2+4/(k−2)≤3, и пришлось бы иметь n<3. Но грань содержит хотя бы3 стороны. Остаются k=3,4,5.','vertex','Неравенство предыдущего шага и целочисленность n,k.'),('Разберём все оставшиеся случаи','При k=3 получаем n<6, то есть n=3,4,5: тетраэдр, куб, додекаэдр. При k=4 имеем n<4, поэтому n=3: октаэдр. При k=5 имеем n<10/3, поэтому снова n=3: икосаэдр. Иных пар нет.','vertex','Исчерпывающий перебор целых чисел в полученных границах.'),('Что доказано и чем подтверждается существование?','Неравенство даёт ровно5 допустимых пар(n,k); само по себе оно не строит тела. Существование подтверждают5 конкретных выпуклых правильных моделей: тетраэдр, куб, октаэдр, додекаэдр, икосаэдр. В статье приводится стандартная классификация этих пяти платоновых типов. Не следует подменять проверку существования одним списком числовых пар.','neutral','Различие необходимых условий и реализации; точные модели пяти тел.'),('Где встречаются эти формы?','Статья иллюстрирует кубические кристаллы соли и пирита, октаэдрические формы флюорита, додекаэдрические формы пирита, икосаэдрические вирусные оболочки и архитектурный тетраэдр в Боттропе. Это примеры геометрического моделирования; реальные объекты могут отклоняться от идеальной правильности.','neutral','Применения математической формы; контекст фотографий статьи.')],'Обозначьте число сторон одной грани и число граней при вершине разными буквами. Сначала получите неравенство, затем переберите целые значения.',[('plato-vertex-angle-sum','Сумма плоских углов при выпуклой вершине меньше360°','theorem',[178]),('plato-five-pairs-proof','Вывод пяти допустимых типов правильных многогранников','proof',[178,179]),('plato-five-existence-models','Пять конкретных платоновых тел','examples',[178]),('plato-nature-architecture','Примеры природных и архитектурных форм','context',[179,180])])

BODY='Геометрическое тело'
def sphere_wire(p,e,key,center,r):
 center=np.array(center,float)
 for plane in range(3):
  axes=[j for j in range(3)if j!=plane];names=[]
  for i in range(24):
   q=center.copy();q[axes[0]]+=r*math.cos(2*math.pi*i/24);q[axes[1]]+=r*math.sin(2*math.pi*i/24)
   name=f'_{key}_{plane}_{i}';p[name]=q;names.append(name)
  e.extend(chain(names))
 return [name for name in p if name.startswith('_'+key+'_')]
p={'O':[0,0,0],'X':[2,0,0],'Y':[2,.4,0],'Z':[2,0,.4],'A':[-3,0,0],'B':[3,0,0]};e=[];outer=sphere_wire(p,e,'outer',[0,0,0],3);inner=sphere_wire(p,e,'inner',[2,0,0],.5)
vis=scene(p,e,[],{'balls':view('Малый шар целиком внутри большого',[['O','X'],['X','Y']],None,['O','X','Y']),'line':view('Шар около X содержит точки вне прямой AB',[['A','B'],['X','Z']],None,['X','Z'])},'Окружности показывают три сечения каждой сферической границы; ломаные лишь приближают окружности на экране. Шар состоит также из всех внутренних точек. OX=2,R=3,r=1/2.')
add(19,7,BODY,'статья: открытая фигура и примеры','Что означает открытая фигура',[180,181],'Дайте определение открытой фигуры в трёхмерном пространстве. Докажите открытость шара без сферы и объясните, почему непустая плоская фигура не открыта в пространстве.',vis,[('Определение с собственным радиусом у каждой точки','Фигура U открыта в пространстве, если для каждой X∈U можно выбрать положительный радиус r так, что весь шар с центром X и радиусом r содержится в U. Радиус разрешается выбирать заново для каждой точки. Весь трёхмерный мир открыт: любой шар вокруг любой точки остаётся в нём.','balls','Определение открытой фигуры.'),('Шар без сферы','Пусть U состоит из точек, удовлетворяющих OX<R. Для данной X возьмём r=(R−OX)/2>0. Если XY≤r, то OY≤OX+XY≤OX+r=(OX+R)/2<R. Значит весь малый шар около X лежит в U. Это доказывает открытость для каждой точки, включая центр.','balls','Неравенство треугольника; положительный запас до границы.'),('Почему это не относится к закрытому шару?','Если X лежит на сфере OX=R, любой шар положительного радиуса около X содержит точки дальше от O, чем R: продолжите луч OX на достаточно короткое расстояние. Такие точки вне исходного шара. Поэтому шар вместе со своей сферой не является открытой фигурой.','balls','Проверка определения на граничной точке.'),('Прямая и плоская фигура','В любой шар около точки прямой AB попадают точки вне этой прямой. Аналогично для любой непустой фигуры в плоскости: короткое движение по перпендикуляру выводит из плоскости, оставаясь в выбранном шаре. Поэтому такие фигуры не открыты именно в трёхмерном пространстве. Слово «открытая» зависит от того, в каком пространстве рассматривают окрестности.','line','Положительный радиус даёт направления во всех трёх измерениях.')],'Рисунок показывает только сечения сфер; в определении нужен целый трёхмерный шар положительного радиуса вокруг каждой точки.',[('body-open-definition','Определение открытой фигуры','definition',[180]),('body-space-open','Всё пространство — открытая фигура','example',[180]),('body-open-ball-proof','Открытый шар: полный пример с радиусом(R−OX)/2','worked_example',[180]),('body-line-plane-not-open','Прямая и непустые плоские фигуры не открыты в пространстве','counterexample',[181])])
p={'O':[0,0,0],'A':[5,0,0],'Y':[4.3,0,0],'P':[-2,-1,0],'Q':[2,-1,0],'X':[-1.8,-1,0]};e=[['P','Q']];sphere_wire(p,e,'ball',[0,0,0],3);sphere_wire(p,e,'outside',[5,0,0],1)
vis=scene(p,e,[],{'outside':view('Окрестность A не встречает исходный шар',[['O','A'],['A','Y']],None,['O','A','Y']),'segment':view('Концы — точки прикосновения интервала',[['P','Q'],['P','X']],None,['P','Q','X'])},'Большой шар имеет R=3, OA=5; малый шар около A имеет радиус1. Отдельный отрезок PQ иллюстрирует интервал без концов: отметки P,Q обозначают исключённые точки, а не их включение.')
add(19,8,BODY,'статья: ограниченность и точки прикосновения','Ограниченность и прикосновение',[181],'Объясните определения ограниченной фигуры и точки прикосновения. Разберите все типовые примеры и докажите, что точка вне шара не является его точкой прикосновения.',vis,[('Ограниченная фигура','Фигура ограничена, если целиком помещается в некоторый шар конечного радиуса. Отрезок, пирамида и шар ограничены. Для пирамиды можно взять шар, содержащий все вершины: он выпуклый, поэтому содержит и все отрезки между их выпуклыми комбинациями, то есть всё тело пирамиды.','segment','Определение ограниченности; выпуклость шара.'),('Неограниченные примеры','Прямая, плоскость и двугранный угол не помещаются ни в какой конечный шар: каждая из этих фигур содержит луч, по которому можно удалиться от любого выбранного центра дальше любого заданного радиуса. Открытость и ограниченность — разные свойства: открытый шар ограничен, всё пространство открыто, но неограничено.','outside','Определение луча и ограниченности.'),('Точка прикосновения','X — точка прикосновения фигуры F, если каждый шар положительного радиуса с центром X содержит хотя бы одну точку F. Любая точка самой фигуры является точкой её прикосновения: центр уже лежит в каждом таком шаре. Это относится, например, ко всем точкам шара или отрезка.','segment','Определение точки прикосновения; принадлежность центра шару.'),('Прикосновение без принадлежности','Удалим из отрезка PQ оба конца. P,Q больше не принадлежат фигуре, но остаются точками прикосновения. Для любого радиуса r>0 выберите точку на PQ на расстоянии меньше min(r,PQ) от соответствующего конца. Она внутри интервала и внутри рассматриваемого шара.','segment','Произвольная положительная окрестность конца содержит внутренние точки интервала.'),('Точка снаружи шара','Пусть OA>R. Выберем r=(OA−R)/2>0. Для любой Y малого шара AY≤r, поэтому OY≥OA−AY≥OA−r=(OA+R)/2>R. Значит малый шар вокруг A не встречает исходный шар. Достаточно одной такой окрестности, чтобы A не была точкой прикосновения.','outside','Обратное неравенство треугольника; отрицание условия «каждый шар».')],'Различайте «точка принадлежит фигуре» и «любая её окрестность встречает фигуру». Для опровержения последнего хватит одной подходящей окрестности.',[('body-bounded-definition','Определение ограниченной фигуры','definition',[181]),('body-bounded-examples','Отрезок, пирамида и шар ограничены; прямая, плоскость и двугранный угол неограничены','examples',[181]),('body-adherence-definition','Определение точки прикосновения','definition',[181]),('body-own-points-adherence','Каждая точка фигуры — точка её прикосновения','example',[181]),('body-open-segment-endpoints','Концы удалённого отрезка остаются точками прикосновения','worked_example',[181]),('body-exterior-ball-gap','Точка вне шара: непересекающаяся окрестность радиуса(OA−R)/2','worked_example',[181])])
p={'O':[-2,0,0],'O1':[2,0,0],'A':[-1,0,0],'I':[-1.1,0,0],'E':[-.9,0,0],'L':[-4,-2,0],'R':[4,-2,0]};e=[];sphere_wire(p,e,'left',[-2,0,0],1);sphere_wire(p,e,'right',[2,0,0],1)
vis=scene(p,e,[],{'separate':view('Два шара с положительным промежутком',None,None,['O','O1']),'boundary':view('Около A есть точки шара и его дополнения',[['O','A'],['I','E']],None,['A','I','E']),'line':view('Отдельный пример связной фигуры: прямая LR',[['L','R']])},'ФигураF — два замкнутых шара радиуса1 с центрами(-2,0,0),(2,0,0). Показанные окружности — сечения границ. ПрямаяLR в отдельном виде служит другим примером и не входит вF.')
add(19,9,BODY,'статья: связность и поверхность','Связность и поверхность фигуры',[182],'Дайте определения связности и поверхности. Проверьте примеры двух раздельных шаров, прямой, плоскости, конуса; объясните, почему поверхность шара — сфера.',vis,[('Точное условие связности','Фигура связна, если при любом её разбиении на две непустые непересекающиеся части хотя бы одна часть содержит точку прикосновения другой. Если найдётся разбиение, в котором ни одна часть не содержит точек прикосновения другой, фигура несвязна. Уточнение «непустые части» существенно.','separate','Определение статьи; смысл разбиения на две части.'),('Два шара — несвязный пример','РазделимF на два составляющих шара. Между ними положительное расстояние2. Вокруг любой точки одного шара можно взять достаточно маленький шар, не встречающий другого; значит эта точка не является точкой прикосновения другой части. Такое разбиение доказывает несвязностьF.','separate','Определение несвязности; положительный промежуток между шарами.'),('Почему выпуклые фигуры связны?','Любые две точки выпуклой фигуры соединяются содержащимся в ней отрезком. Если существовало бы разбиение без взаимных точек прикосновения, вдоль отрезка получились бы две непустые отделённые части интервала. Но интервал нельзя так разделить: при переходе от одной части к другой возникает их граничная точка, принадлежащая интервалу и являющаяся точкой прикосновения другой части. Подробное объяснение этого факта приведено в подсказке. Поэтому прямая, плоскость и обычный сплошной выпуклый конус связны.','line','Выпуклость; связность отрезка; определение точки прикосновения.'),('Что называют поверхностью?','ПоверхностьF состоит из точек, являющихся точками прикосновения иF, и его дополнения — множества всех точек пространства внеF. Иначе говоря, любой шар вокруг такой точки встречает обе фигуры. Поверхность может содержать точки, не принадлежащие самойF.','boundary','Определение поверхности через два условия прикосновения.'),('Проверим шар и многогранник','Если OA=R, в любом шаре околоA есть точки с расстоянием отO меньшеR и большеR;A принадлежит поверхности шара. Для внутренней точки можно выбрать окрестность целиком внутри шара, для внешней — целиком снаружи. Поэтому поверхность шара — ровно сфера. У многогранника поверхность образуют все грани, включая их рёбра и вершины: около любой такой точки есть точки тела и точки вне него.','boundary','Положительный запас до границы и определение поверхности.')],'Для связности ищите разделение с настоящим разрывом. Для поверхности одновременно проверяйте наличие рядом точек фигуры и её дополнения.',[('body-connected-definition','Определение связной фигуры','definition',[182]),('body-two-balls-disconnected','Два раздельных шара — несвязная фигураF','counterexample',[182]),('body-connected-examples','Прямая, плоскость и конус — связные фигуры','examples',[182]),('body-boundary-definition','Определение поверхности фигуры','definition',[182]),('body-boundary-examples','Сфера — поверхность шара; объединение граней — поверхность многогранника','examples',[182])])
