file=OUT/'theory-19-detail-09.json';d=json.loads(file.read_text());d['help'].append({'id':'help-interval','question':'Почему отрезок нельзя разделить на две отделённые части?','text':'Параметризуем отрезок числамиt∈[0,1]. Если частиE,F не содержат точек прикосновения друг друга, каждая точка имеет маленький интервал, целиком лежащий в её части. Пусть0∈E,1∈F. Рассмотрим наибольшую границуc, до которой весь начальный отрезок принадлежитE. Окрестности0 и1 дают0<c<1. ТочкиE подходят кc слева. Еслиc∈F, оно — точка прикосновенияE, что запрещено. Еслиc∈E, маленький интервал вокругc лежит вE и позволяет продлить начальный отрезок дальшеc, тоже противоречие. Значит такого разбиения нет. Здесь используется привычное свойство непрерывного числового отрезка — существование точной верхней грани.','children':[]});file.write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
p={'O':[-2,0,0],'O1':[2,0,0],'A':[-1,0,0],'B':[1,0,0],'X':[0,0,0],'Y':[0,.25,0]};e=[['A','B']];sphere_wire(p,e,'left',[-2,0,0],1);sphere_wire(p,e,'right',[2,0,0],1);sphere_wire(p,e,'tiny',[0,0,0],.25)
vis=scene(p,e,[],{'join':view('ФигураG: два шара и тонкий отрезок',[['A','B']],None,['O','O1','A','B']),'notinside':view('Ни один малый шар вокруг X не лежит вG',[['X','Y'],['A','B']],None,['X','Y'])},'Контрпример G из рис.16.2: два шара соединены отрезком нулевой толщины. Рамки сфер — схематические окружности, соединитель AB — точный отрезок. Малый шар около X содержит Y∉G.')
add(19,10,BODY,'статья: строгое определение тела и контрпримеры','Когда фигура является телом',[180,182,183,148],'Сформулируйте строгое определение геометрического тела. Обоснуйте примеры и исключите фигурыF,G с рисунка16.2, не путая связность фигуры со связностью её открытой внутренней части.',vis,[('Определение тела','Телом называют ограниченную фигуру, которую можно получить как объединение непустой связной открытой фигурыU и её поверхности. Здесь открытость понимается в трёхмерном пространстве. Требуются все условия: ограниченность результата, непустота, связность и открытостьU, а также добавление всей её поверхности.','join','Строгое определение в статье «Геометрическое тело».'),('Положительные примеры','Для шара берём открытый шар без сферы. Он непуст, открыт и выпуклый, значит связен; его поверхность — сфера. Добавляя её, получаем ограниченный замкнутый шар. Аналогично внутренность выпуклого многогранника или сплошного конуса открыта и связна; добавив грани или граничные поверхности, получаем тело. У выпуклого многогранника внутренность непуста, если он невырожден и имеет пространственный объём.','join','Ранее доказанные свойства открытого шара, связности и поверхности.'),('Почему прямая, плоскость и двугранный угол не тела?','Все три неограничены. Кроме того, прямая и плоскость не содержат ни одного трёхмерного шара, поэтому не могут содержать требуемую непустую открытуюU. Даже ограниченный отрезок не тело по этой второй причине.','notinside','Необходимые условия определения тела.'),('ПочемуF из двух раздельных шаров не тело?','Любая открытаяU⊂F лежит в объединении двух открытых шаров. ЕслиU касается обоих, положительный промежуток разделяет её на две непустые отделённые части, и она несвязна. ЕслиU лежит только в одном шаре, добавление её поверхности не создаст второй шар на положительном расстоянии. Поэтому получить всёF по определению нельзя.','join','Рис.16.2; определение связности и прикосновения.'),('Почему соединительный отрезок не исправляетG?','G связна: между любыми двумя точками можно пройти через шары и соединитель. Но внутренняя точка соединительного отрезка не имеет ни одной трёхмерной окрестности, лежащей вG. Поэтому любая открытаяU⊂G по-прежнему лежит внутри двух раздельных открытых шаров. СвязнаяU не может охватывать оба; её поверхность также не восстановит другой шар. Следовательно,G не тело. Причина — отсутствие связной открытой пространственной части, а не несвязность самойG.','notinside','Связность и открытость — разные свойства; контрпримеррис.16.2.'),('Зачем вводились эти определения?','Открытые множества, точки прикосновения и связность изучаются в топологии. В исторической справке учебник выделяет П.С.Александрова(1896–1982) и П.С.Урысона(1898–1924), сыгравших важную роль в её развитии. Биографические примеры показывают связь школьной геометрии с последующей математикой; они не добавляют нового задания на вычисление.','join','Историческая справка на печатнойстр.182.')],'Связная фигура не обязательно тело. У соединителя нулевая толщина: вокруг его внутренней точки любой пространственный шар выходит наружу.',[('body-solid-definition','Строгое определение тела','definition',[182]),('body-solid-positive-examples','Шар, многогранник, конус как тела','examples',[180,182]),('body-solid-nonexamples','Прямая, плоскость, двугранный угол и фигурыF,G не являются телами','proof_prompt',[182,148]),('body-topology-context','Топология и исторические справки Александрова/Урысона','context',[182,183])])

# Keep prose readable without altering identifiers or coordinates.
def readable(value):
 if isinstance(value,str):
  value=re.sub(r'(?<=[А-Яа-яЁё])(?=[A-Za-z0-9])|(?<=[A-Za-z0-9])(?=[А-Яа-яЁё])',' ',value)
  return value.replace('рис.16.2','рис. 16.2').replace('задача6.25','задача 6.25').replace('проекте3','проекте 3').replace('стр.182','стр. 182')
 if isinstance(value,list):return [readable(x)for x in value]
 if isinstance(value,dict):return {k:readable(v)for k,v in value.items()}
 return value
for c in CARDS:
 file=ROOT/c['lessonFile'];d=readable(json.loads(file.read_text()));file.write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n')

